const {nearestRatio,RATIOS}=require('./cloneBatch.cjs');
const REF_ROLES={product:'Sản phẩm gốc',mood:'Mood / concept',texture:'Texture / chi tiết',camera:'Góc camera',outfit:'Trang phục',pose:'Posing mẫu',color:'Màu sắc',style:'Phong cách & ánh sáng',material:'Chất liệu',accessory:'Phụ kiện / vật thể',background:'Bối cảnh',identity:'Nhận diện bổ sung'};
const OPERATIONS={editMaterial:'Đổi chất liệu',editAccessory:'Thêm / thay phụ kiện',editOutfit:'Thay trang phục',editPose:'Đổi dáng',editCamera:'Góc máy & bố cục',editColor:'Chỉnh màu theo ref',editStyle:'Phong cách & ánh sáng',editBackground:'Thay bối cảnh',editExpression:'Biểu cảm theo ref dáng'};
const FINISHES={source:{label:'Theo ảnh gốc / ref',text:''},natural:{label:'Natural · da & chất liệu thật',text:'Ảnh chụp tự nhiên, da có lỗ chân lông và độ chuyển sáng tự nhiên, tóc tách sợi, chất liệu thật, bóng đổ hợp lý; giữ bất đối xứng tự nhiên, không làm đẹp khuôn mặt quá mức.'},softFilm:{label:'Soft film · dịu, trung tính',text:'Cảm giác film dịu, chuyển vùng sáng mềm, tương phản vừa, màu trung tính, chi tiết da và chất liệu tự nhiên; không thêm viền phim hoặc chữ.'},warmFilm:{label:'35mm warm · ấm nhẹ',text:'Cảm giác ảnh film 35mm, vùng sáng ấm nhẹ, tương phản vừa, chuyển sắc mềm và chất liệu hữu cơ; không phủ màu cam lên da, không đổi màu nhận diện quần áo/sản phẩm.'},editorial:{label:'Editorial · texture rõ, không HDR',text:'Ảnh editorial có texture da, tóc và vải chân thật, ánh sáng có chủ đích, vi tương phản vừa đủ; không da nhựa, không làm nét viền quá mức hoặc HDR gắt.'}};
const NEGATIVES={none:{label:'Tắt negative mẫu',text:''},natural:{label:'Tự nhiên · hạn chế vẻ AI',text:'waxy or plastic skin, excessive airbrushing, artificial facial symmetry, generic beauty face replacing identity, oversharpened edges, crunchy HDR, fake bokeh, smeared fabric texture, inconsistent shadows, warped anatomy, fused or extra fingers, duplicate subject, garbled new text, new watermark'},fashion:{label:'Fashion · mặt, dáng & vải',text:'identity drift, face swap, wrong garment design, melted seams, smeared fabric, incorrect logos, inconsistent accessories, impossible clothing folds, warped hands, extra fingers, distorted body proportions, plastic skin, beauty-filter face, crunchy HDR, new watermark'},product:{label:'Sản phẩm · hình học & nhãn',text:'warped product geometry, changed branding, unreadable altered label, invented packaging, melted material, fake reflections, oversharpened edges, plastic-looking surfaces, inconsistent lighting, unwanted added text, new watermark'}};
const COMBINED_DEFAULTS={multiEdit:true,cloneColor:true,poseMatch:'exact',editOutfit:false,editMaterial:false,editAccessory:false,editPose:false,editCamera:false,editColor:false,editStyle:false,editBackground:false,editExpression:false,colorScope:'grade',finish:'source',grain:'none',negativePreset:'natural',negativeText:'',outputSize:'original',transferTarget:'',ratioMode:'auto',ratio:'3:4',text:''};
function roleEnabled(role,d){return ['product','mood','texture'].includes(role)&&d.productStudio===true||role==='camera'&&d.editCamera||role==='material'&&d.editMaterial||role==='accessory'&&d.editAccessory||role==='identity'||role==='outfit'&&d.editOutfit||role==='pose'&&(d.editPose||d.editCamera||d.editExpression)||role==='color'&&d.editColor&&d.cloneColor!==false||role==='style'&&d.editStyle||role==='background'&&d.editBackground}
function settingsErrors(d){const e=[];if(d.cloneColor!==undefined&&typeof d.cloneColor!=='boolean')e.push('Clone màu không hợp lệ');if(d.poseMatch!==undefined&&!['exact','similar'].includes(d.poseMatch))e.push('Mức khớp dáng không hợp lệ');if(d.outputSize!==undefined&&!['original','2k','4k'].includes(d.outputSize))e.push('Kích thước xuất không hợp lệ');if(d.transferTarget!==undefined&&(typeof d.transferTarget!=='string'||d.transferTarget.length>1000))e.push('Vùng chỉnh sửa tối đa 1.000 ký tự');if(d.multiEdit!==true)return e;for(const key of Object.keys(OPERATIONS))if(d[key]!==undefined&&typeof d[key]!=='boolean')e.push('Tùy chọn chỉnh kết hợp không hợp lệ');if(d.ratioMode!==undefined&&!['auto','master','manual',...Object.keys(REF_ROLES).map(r=>'role:'+r)].includes(d.ratioMode))e.push('Nguồn Auto ratio không hợp lệ');if(d.colorScope!==undefined&&!['grade','garment'].includes(d.colorScope))e.push('Phạm vi chỉnh màu không hợp lệ');if(!Object.hasOwn(FINISHES,d.finish||'natural'))e.push('Preset film không hợp lệ');if(!['none','light','medium'].includes(d.grain||'light'))e.push('Mức grain không hợp lệ');if(!Object.hasOwn(NEGATIVES,d.negativePreset||'natural'))e.push('Mẫu hạn chế lỗi không hợp lệ');if(d.negativeText!==undefined&&(typeof d.negativeText!=='string'||d.negativeText.length>4000))e.push('Chi tiết cần tránh bổ sung tối đa 4.000 ký tự');return e}
function combinedInstruction(d){if(d.photoOutcomeVersion===2&&typeof d.photoOutcomeContract==='string')return d.photoOutcomeContract;const yes=key=>d[key]===true;return [
d.cloneColor===false?'CLONE KHÔNG MÀU: chỉ sao chép chính xác thiết kế, hình dáng, họa tiết và chi tiết ref theo vai trò; giữ màu gốc của vùng tương ứng trên MASTER, không lấy palette ref.':'CLONE CHÍNH XÁC: bám sát thiết kế, hình học, chi tiết và màu tham chiếu theo đúng vai trò; không sáng tạo lại hoặc thay bằng mẫu gần giống.',
'CHỈNH KẾT HỢP TRONG MỘT ẢNH. BASE là MASTER: giữ danh tính, cấu trúc khuôn mặt, tóc, tỷ lệ cơ thể và đặc điểm bất đối xứng. Nếu thao tác không có ref riêng, làm theo mô tả bằng chữ; không tự mượn thuộc tính từ ref vai trò khác. Mọi ref chỉ có quyền quyết định thuộc tính đúng vai trò đã gán. Không thay người gốc bằng người trong ref.',
d.transferTarget?.trim()?'VÙNG CHỈNH SỬA: '+d.transferTarget.trim()+'. Chỉ chỉnh thuộc tính yêu cầu trong vùng này; giữ nguyên vùng còn lại. Đây là vùng mô tả bằng chữ, không phải mặt nạ pixel.':'',
yes('editMaterial')?'CHẤT LIỆU: chuyển vân, độ bóng, độ nhám và phản xạ của ref Chất liệu vào vùng được yêu cầu; giữ đường biên, phom và nhận diện, không lấy mặt hay tư thế từ ref.':'',
yes('editAccessory')?'PHỤ KIỆN: thêm hoặc thay phụ kiện/vật thể theo ref Phụ kiện và mô tả, đúng vị trí, tỉ lệ và bóng tiếp xúc; không đổi danh tính hoặc vùng khác.':'',
yes('editOutfit')?'TRANG PHỤC: lấy thiết kế, '+(d.cloneColor===false?'giữ màu MASTER, lấy vật liệu':'màu vật liệu')+', họa tiết, đường may, giày/phụ kiện từ ref Trang phục, mặc tự nhiên trên MASTER. Không lấy dáng, mặt hay nền từ ref trang phục.':`KHÓA TRANG PHỤC MASTER: giữ thiết kế, ${yes('editColor')&&d.colorScope==='garment'?'chỉ đổi màu theo ref Màu sắc, giữ nguyên':'giữ màu vật liệu gốc cùng'} ${yes('editMaterial')?'chỉ cho phép đổi chất liệu theo yêu cầu':'giữ chất liệu gốc'}, họa tiết, ${yes('editAccessory')?'chỉ đổi phụ kiện theo yêu cầu':'giữ giày/phụ kiện gốc'}. Chỉ cho phép nếp gấp thích nghi tư thế mới.`,
yes('editPose')&&d.poseMatch==='similar'?'DÁNG TƯƠNG TỰ: lấy cảm giác, hành động và hướng chính từ ref; cho phép tay chân và trọng tâm thích nghi tự nhiên với MASTER.':yes('editPose')?'DÁNG CHÍNH XÁC 100% THEO REF: lấy hướng đầu/thân, vai/hông, trọng tâm và vị trí tay chân từ ref Dáng & góc máy; không ép nhân vật nhìn thẳng máy. Khớp hướng mắt, góc nghiêng, góc quay đầu và mức che khuất khuôn mặt trong ref; nếu quay lưng hoặc không thấy mặt thì giữ như ref, không tự xoay mặt về camera.':'Giữ tư thế MASTER.',
yes('editCamera')?'MÁY ẢNH: tự fit toàn bộ chủ thể trong khung, không cắt đầu, tay chân hoặc sản phẩm. Khớp bố cục ref và tự điều chỉnh khoảng cách máy. Lấy góc máy, độ cao, hướng máy, cỡ cảnh, phối cảnh và khoảng trống theo ref Dáng & góc máy.':'Giữ góc máy và bố cục MASTER.',
yes('editExpression')?'BIỂU CẢM: theo ref Dáng & góc máy nhưng giữ cấu trúc mặt MASTER.':'Giữ sắc thái biểu cảm MASTER; ánh mắt thích nghi tự nhiên với hướng đầu.',
yes('editStyle')?'STYLE: lấy cách chiếu sáng, tương phản, độ mềm và ngôn ngữ chụp từ ref Phong cách & ánh sáng; không lấy quần áo, dáng hoặc người trong ref này.':'Giữ phong cách và chất lượng ánh sáng MASTER, sau đó áp finishing đã chọn.',
yes('editColor')&&d.colorScope==='garment'?'MÀU: đổi màu trang phục theo ref Màu sắc, giữ thiết kế và texture của trang phục đang chọn; không lấy hình dáng quần áo hoặc người trong ref màu. Màu ref ưu tiên hơn màu trang phục cũ và preset film.':yes('editColor')?'MÀU: ưu tiên palette, cân bằng trắng và quan hệ màu vùng sáng/tối của ref Màu sắc. Đây là color grading; giữ màu nhận diện của quần áo/sản phẩm, không đổi thiết kế. Ref màu ưu tiên hơn tông của preset film.':'Giữ màu nhận diện của MASTER hoặc trang phục được chọn, không tự lấy màu từ ref vai trò khác.',
yes('editBackground')?'BỐI CẢNH: theo ref Bối cảnh, hòa tỷ lệ, phối cảnh, ánh sáng và bóng tiếp xúc tự nhiên.':'Giữ bối cảnh MASTER, không đưa đồ vật hoặc nền của ref khác vào ảnh.',
'Nhiều ref cùng một vai trò: ảnh đầu tiên là chính, ảnh sau chỉ bổ sung chi tiết tương thích. Nếu xung đột giữa các ref, tuân theo vai trò của từng ảnh; không trộn mặt hoặc cộng thêm người. Xuất một ảnh hoàn chỉnh, không collage, không hiển thị ref.',
FINISHES[d.finish||'natural']?.text,
yes('editColor')?'Chỉ áp đặc tính texture và chuyển sáng của preset finishing; màu từ ref Màu sắc được ưu tiên.':'',
d.grain==='none'?'Không thêm grain hoặc noise nhân tạo.':d.grain==='medium'?'Thêm film grain hữu cơ vừa phải, hạt mịn ngẫu nhiên, giữ rõ mặt, vải và chi tiết sản phẩm; không tạo vết bẩn hoặc banding.':'Hạt phim rất nhẹ và tinh, cảm nhận ở vùng trung tính, không làm bẩn da hoặc mất chi tiết.',
'Ưu tiên chi tiết gốc: sợi vải, đường may, lỗ chân lông, tóc tách sợi và đường biên tự nhiên. Không làm mịn, không beauty filter, không giảm chi tiết để tối ưu dung lượng. Độ phân giải thật phụ thuộc model; hậu kỳ tăng kích thước không tạo lại chi tiết đã mất.',
'Chống vẻ ảnh tổng hợp: độ sắc nét hợp lý, texture không lặp, tay/chân tự nhiên, ánh sáng và bóng nhất quán. Không tự đổi gương mặt để làm đẹp.'
].filter(Boolean).join('\n')}
function negativeInstruction(d){return [NEGATIVES[d.negativePreset||'natural']?.text,d.negativeText?.trim()].filter(Boolean).join(', ')}
function describeRoleRefs(guide){return (guide?.roleRefs||[]).map((r,i)=>`${i+1}. @${r.tag}: ${REF_ROLES[r.role]||'Chưa gán vai trò'}`).join('\n')}
function buildCombinedGraph({base,refsByRole={},settings={},dimensions={},make,edge}){const d={...COMBINED_DEFAULTS,...settings,multiEdit:true};if(d.cloneColor===false)d.editColor=false;if(!base)throw Error('Chọn ảnh nhân vật gốc');const err=settingsErrors(d);if(err.length)throw Error(err.join('\n'));if(!Object.keys(OPERATIONS).some(key=>d[key])&&!d.text?.trim()&&d.finish==='source'&&d.grain==='none')throw Error('Nhập mô tả chỉnh sửa hoặc chọn ít nhất một thuộc tính muốn thay đổi');for(const role of Object.keys(REF_ROLES))if(role!=='identity'&&roleEnabled(role,d)&&!refsByRole[role]?.length&&!d.text?.trim())throw Error('Thêm ảnh ref cho '+REF_ROLES[role]);const chosen=Object.entries(refsByRole).filter(([role])=>roleEnabled(role,d)).flatMap(([role,tags])=>[...new Set(tags)].map(tag=>({role,tag})));let ratio=d.ratio;if(d.ratioMode!=='manual'){let target=base;if(d.ratioMode!=='master'){const preferred=d.ratioMode?.startsWith('role:')?d.ratioMode.slice(5):['camera','pose','background','style','outfit','color'].find(role=>chosen.some(x=>x.role===role));if(d.ratioMode?.startsWith('role:')&&!chosen.some(x=>x.role===preferred))throw Error('Chọn ref đang dùng cho Auto ratio');target=chosen.find(x=>x.role===preferred)?.tag||base}const dim=dimensions[target];if(!dim)throw Error('Không đọc được kích thước ảnh dùng làm khung');ratio=nearestRatio(dim.width,dim.height)}if(!RATIOS.includes(ratio))throw Error('Tỉ lệ không được hỗ trợ');const aliases=new Map([[base.toLowerCase(),'ảnh gốc MASTER']]);for(const {role,tag} of chosen){const prior=aliases.get(tag.toLowerCase());aliases.set(tag.toLowerCase(),prior?prior+' / '+REF_ROLES[role]:'ảnh tham chiếu '+REF_ROLES[role])}const prompt=String(d.text||'').replace(/@([\p{L}\p{N}_-]+)/gu,(mention,tag)=>aliases.get(tag.toLowerCase())||mention);const source=make('source',0,80,{refTag:base,label:'MASTER · Danh tính gốc'}),edit=make('image',480,80,{...d,ratio,label:'Chỉnh kết hợp · '+ratio,text:prompt.trim()||'Áp dụng đồng thời các thao tác đã bật và đúng vai trò từng ref; giữ danh tính nhân vật MASTER.'}),out=make('output',900,80,{label:'Ảnh kết hợp'}),nodes=[source,edit,out],edges=[edge(source,edit),edge(edit,out)],byTag=new Map([[base,source]]);chosen.forEach(({role,tag},i)=>{if(!byTag.has(tag)){const n=make('source',0,430+i*300,{refTag:tag,label:REF_ROLES[role]+' · @'+tag});byTag.set(tag,n);nodes.push(n)}const e=edge(byTag.get(tag),edit,'guide');e.data={...e.data,role};edges.push(e)});return {reviewBeforeNext:true,nodes,edges,viewport:{x:50,y:60,zoom:.65}}}
module.exports={REF_ROLES,OPERATIONS,FINISHES,NEGATIVES,COMBINED_DEFAULTS,roleEnabled,settingsErrors,combinedInstruction,negativeInstruction,describeRoleRefs,buildCombinedGraph};
